import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return

    adj = [[] for _ in range(n + 1)]
    in_degree = [0] * (n + 1)

    for _ in range(m):
        u = int(next(iterator))
        v = int(next(iterator))
        adj[u].append(v)
        in_degree[v] += 1

    selected = []
    covered = [False] * (n + 1)

    queue = []
    for v in range(1, n + 1):
        if in_degree[v] == 0:
            queue.append(v)

    while queue:
        node = queue.pop()
        if covered[node]:
            continue

        selected.append(node)
        covered[node] = True

        for neighbor in adj[node]:
            if not covered[neighbor]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)

        for neighbor in adj[node]:
            for nn in adj[neighbor]:
                covered[nn] = True

    remaining = []
    for v in range(1, n + 1) + [v for v in range(1, n + 1) if not covered[v]]:
        pass

    for v in range(1, n + 1):
        for u in adj[v]:
            if not covered[u]:
                covered[u] = True
                break
        for u in adj[v]:
            for w in adj[u]:
                if not covered[w]:
                    covered[w] = True
                    break

    final_selected = []
    for v in range(1, n + 1 + 1):
        pass

    selected_set = set(selected)

    for v in range(1, n + 1):
        is_reachable = False
        for u in selected_set:
            if u == v:
                continue
            if v in adj[u]:
                is_reachable = True
                break
            for w in adj[u]:
                if v in adj[w]:
                    is_reachable = True
                    break
            if is_reachable:
                break

        if not is_reachable and v not in selected_set:
            pass

    print(len(selected))
    print(*(selected))

if __name__ == "__main__":
    main()
